<script setup lang="ts">import { computed,watchEffect } from 'vue';import { useSettingsStore } from '../stores/settings.store';import { useWeatherStore } from '../stores/weather.store';import { useCalendarStore } from '../stores/calendar.store';const settings=useSettingsStore(),weather=useWeatherStore(),cal=useCalendarStore();const yearProgress=computed(()=>{const n=new Date(),a=new Date(n.getFullYear(),0,1),b=new Date(n.getFullYear()+1,0,1);return Math.max(0,Math.min(100,((+n-+a)/(+b-+a))*100))});const upcoming=computed(()=>cal.sortedEvents.filter(e=>+new Date(e.end||e.start)>=Date.now()).slice(0,2));let weatherKey='';watchEffect(()=>{if(settings.data.weatherEnabled&&settings.data.latitude!=null&&settings.data.longitude!=null){const key=`${settings.data.latitude.toFixed(3)},${settings.data.longitude.toFixed(3)}`;if(key!==weatherKey){weatherKey=key;void weather.load(settings.data.latitude,settings.data.longitude)}}})</script><template><div class="info-grid"><article class="info-card"><div class="eyebrow">Meteo</div><strong v-if="settings.data.weatherEnabled && weather.temperature!=null">{{Math.round(weather.temperature)}}°</strong><span v-if="settings.data.weatherEnabled">{{weather.condition || 'Aggiornamento…'}}</span><span v-else class="muted">Attivalo nelle impostazioni</span></article><article class="info-card"><div class="eyebrow">Verso il {{new Date().getFullYear()+1}}</div><strong>{{yearProgress.toFixed(1)}}%</strong><span class="muted">del {{new Date().getFullYear()}} vissuto</span><div class="bar"><i :style="{width:`${yearProgress}%`}"/></div></article><article class="info-card agenda"><div class="eyebrow">Agenda</div><template v-if="upcoming.length"><div v-for="e in upcoming" :key="e.id" class="event"><b>{{new Date(e.start).toLocaleDateString('it-IT',{day:'2-digit',month:'short'})}}</b><span>{{e.title}}</span></div></template><span v-else class="muted">Nessun appuntamento vicino</span></article></div></template><style scoped>.info-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.info-card{min-height:108px;border-top:1px solid var(--glass-border);padding:.9rem .55rem .35rem;display:flex;flex-direction:column;gap:.25rem}.info-card strong{font-size:1.55rem;font-weight:540}.info-card span{font-size:var(--font-sm)}.bar{height:3px;background:rgba(255,255,255,.12);border-radius:4px;margin-top:auto;overflow:hidden}.bar i{display:block;height:100%;background:var(--accent)}.event{display:flex;gap:.55rem;align-items:baseline;font-size:var(--font-sm)}.event b{font-size:var(--font-xs);color:var(--accent);text-transform:uppercase}@media(max-width:600px){.info-grid{grid-template-columns:1fr;gap:0}.info-card{min-height:auto;padding:1rem .2rem}.info-card strong{font-size:1.25rem}} </style>
